package propertyrental.platform.listing.application.mapper;

import org.springframework.stereotype.Component;
import propertyrental.platform.listing.api.dto.request.CreateListingStatusRequest;
import propertyrental.platform.listing.api.dto.request.UpdateListingStatusRequest;
import propertyrental.platform.listing.api.dto.response.ListingStatusResponse;
import propertyrental.platform.listing.infrastructure.persistence.entity.ListingStatusEntity;

@Component
public class ListingStatusMapper {

    // this build new entity from a create request (id is generated by the database)
    public ListingStatusEntity toEntity(CreateListingStatusRequest request){
      ListingStatusEntity status = new ListingStatusEntity();
      status.setCode(request.code());
      status.setName(request.name());

      return status;
    }

    public void updateEntity(ListingStatusEntity status, UpdateListingStatusRequest request) {
        status.setCode(request.code());
        status.setName(request.name());
    }

    // This one convert entity to the response dto (entity is never exposed)
    public ListingStatusResponse toResponse(ListingStatusEntity status) {

        return new ListingStatusResponse(
                status.getId(),
                status.getCode(),
                status.getName()
        );
    }
}
